import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { EventEmitter } from 'events';
import http from 'http';
import https from 'https';
import {
  applyProxyUrl,
  applyProxyMode,
  applyProxyEnabled,
  applyProxyBypass,
  getProxyUrl,
  getProxyMode,
  isProxyEnabled,
  getProxyBypassPlatforms,
  getNoProxyRules,
  isProxyActive,
  isSocksProxyUrl,
  socksHostnameLookup,
  PROXY_SCHEMES,
  PROXY_MODES,
  proxyFetch,
  describeAbort,
  withKeyProxy,
  probeProxyUrl,
  DEFAULT_PROXY_PROBE_TARGET,
  parseScutilProxy,
  parseRegProxy,
