/**
 * Deep sanitize Gemini tool definitions to ensure that any object parameters
 * have valid properties and items, preventing missing field errors (e.g. missing
 * items on array schemas or missing properties on object schemas).
 */
function sanitizeGeminiTools(tools: unknown): unknown {
  if (!Array.isArray(tools)) return tools;
  return tools.map((tool) => {
    if (!tool || typeof tool !== 'object') return tool;
    const t = tool as Record<string, unknown>;
    if (Array.isArray(t.function_declarations)) {
      t.function_declarations = t.function_declarations.map((decl) => {
        if (!decl || typeof decl !== 'object') return decl;
        const d = decl as Record<string, unknown>;
        if (d.parameters && typeof d.parameters === 'object') {
          d.parameters = sanitizeJsonSchema(d.parameters);
        }
        return d;
      });
    }
    return t;
  });
}

function sanitizeJsonSchema(schema: unknown): unknown {
  if (!schema || typeof schema !== 'object') return schema;
  const s = { ...(schema as Record<string, unknown>) };

  if (s.type === 'object') {
    if (!s.properties || typeof s.properties !== 'object' || s.properties === null) {
      s.properties = {};
    } else {
      const props = { ...(s.properties as Record<string, unknown>) };
      for (const [key, val] of Object.entries(props)) {
        props[key] = sanitizeJsonSchema(val);
      }
      s.properties = props;
    }
  } else if (s.type === 'array') {
    if (!s.items || typeof s.items !== 'object' || s.items === null) {
      s.items = { type: 'string' };
    } else {
      s.items = sanitizeJsonSchema(s.items);
    }
  }

  // Also recursively sanitize items/properties if present regardless of explicit type
  if (s.properties && typeof s.properties === 'object' && s.properties !== null) {
    const props = { ...(s.properties as Record<string, unknown>) };
    for (const [key, val] of Object.entries(props)) {
      props[key] = sanitizeJsonSchema(val);
    }
    s.properties = props;
  }
  if (s.items) {
    if (Array.isArray(s.items)) {
      s.items = s.items.map((item) => sanitizeJsonSchema(item));
    } else {
      s.items = sanitizeJsonSchema(s.items);
    }
  }

  return s;
}

